    SONRAKI: 'UF_CRM_EFAS_AI_NEXT', // bir sonraki arama zamanı
    SONUC: 'UF_CRM_EFAS_AI_RES', // son sonuç (ARANIYOR, ULASILAMADI, TEKRAR_ARA, RANDEVU, OLUMSUZ...)
    CAGRI: 'UF_CRM_EFAS_AI_CALL', // son Vapi call ID
