    BASLIK: 'SMS_BASLIGINIZ', // Netgsm'de onaylı gönderici başlığı
    IYS_FILTRE_TICARI: '11', // tanıtım SMS'i: 11 = bireysel İYS onayı olanlara gider, 12 = tacir
    METIN: {
